module tb_TopModule;
    reg a;
    reg b;
    wire out_and;
    wire out_or;
    wire out_xor;
    wire out_nand;
    wire out_nor;
    wire out_xnor;
    wire out_anotb;

    TopModule u_ut (
        .a(a),
        .b(b),
        .out_and(out_and),
        .out_or(out_or),
        .out_xor(out_xor),
        .out_nand(out_nand),
        .out_nor(out_nor),
        .out_xnor(out_xnor),
        .out_anotb(out_anotb)
    );

    initial begin
        integer i;
        for (i = 0; i < 4; i = i + 1) begin
            {a, b} = i[1:0];
            #10;
            // Expected values
            if (out_and !== (a & b)) begin
                $display("SELFTEST FAIL: out_and mismatch for a=%b b=%b", a, b);
                $finish;
            end
            if (out_or !== (a | b)) begin
                $display("SELFTEST FAIL: out_or mismatch for a=%b b=%b", a, b);
                $finish;
            end
            if (out_xor !== (a ^ b)) begin
                $display("SELFTEST FAIL: out_xor mismatch for a=%b b=%b", a, b);
                $finish;
            end
            if (out_nand !== ~(a & b)) begin
                $display("SELFTEST FAIL: out_nand mismatch for a=%b b=%b", a, b);
                $finish;
            end
            if (out_nor !== ~(a | b)) begin
                $display("SELFTEST FAIL: out_nor mismatch for a=%b b=%b", a, b);
                $finish;
            end
            if (out_xnor !== ~(a ^ b)) begin
                $display("SELFTEST FAIL: out_xnor mismatch for a=%b b=%b", a, b);
                $finish;
            end
            if (out_anotb !== (a & ~b)) begin
                $display("SELFTEST FAIL: out_anotb mismatch for a=%b b=%b", a, b);
                $finish;
            end
        end
        $display("SELFTEST PASS");
        $finish;
    end
endmodule
